window.VF1_UNITS = {"4":{"unit":4,"code":"VF1-U04","title":"Friends & Relations","startNumber":77,"endNumber":103,"entries":[{"number":77,"term":"apologize to sb for doing st · apology","sourceTerm":"apologize (v) to sb for doing st · apology (n)","spoken":"apologize to somebody for doing something · apology","ipa":"/əˈpɑːləˌdʒaɪz tuː ˈsʌˌmbɑːdi fɔːr ˈduːɪŋ ˈsʌmθɪŋ əˈpɑːləˌdʒi/","type":"verb · noun","meaning":"xin lỗi ai vì đã làm gì · lời xin lỗi","definition":"To say sorry to someone for something; a statement of regret.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: apologize (v) to sb for doing st · apology (n)","example":"Mai apologized to her friend for sharing the message, and her apology was accepted."},{"number":78,"term":"defend · defense","sourceTerm":"defend (v) · defense (n)","spoken":"defend · defense","ipa":"/dɪˈfɛnd dɪˈfɛns/","type":"verb · noun","meaning":"bảo vệ, phòng thủ · sự bảo vệ, sự phòng thủ","definition":"To protect someone or something; the act of protecting.","note":"","example":"A good friend may defend you, but your best defense is to tell the truth."},{"number":79,"term":"divorce · divorced","sourceTerm":"divorce (v,n) · divorced (a)","spoken":"divorce · divorced","ipa":"/dɪˈvɔːrs dɪˈvɔːrst/","type":"verb · noun · adjective","meaning":"li hôn; sự li hôn · đã li hôn","definition":"To legally end a marriage; no longer married.","note":"","example":"Her parents divorced last year, and after the divorce they both cared for her."},{"number":80,"term":"generous >< mean","sourceTerm":"generous (a) >< mean (a)","spoken":"generous >< mean","ipa":"/ˈdʒɛnɚəs miːn/","type":"adjective","meaning":"hào phóng, rộng lượng · keo kiệt","definition":"Willing to give and share; unwilling to give.","note":"mean ở đây là keo kiệt hoặc không tử tế; mean còn có thể là “có nghĩa là”; danh từ mean là “mức trung bình”.","example":"A generous person shares with others, while a mean person refuses to help."},{"number":81,"term":"grateful to sb for st · gratitude","sourceTerm":"grateful (a) to sb for st · gratitude (n)","spoken":"grateful to somebody for something · gratitude","ipa":"/ˈɡreɪtfəl tuː ˈsʌˌmbɑːdi fɔːr ˈsʌmθɪŋ ˈɡrætəˌtuːd/","type":"noun · adjective","meaning":"biết ơn ai vì điều gì · lòng biết ơn","definition":"Feeling thankful to someone; the feeling of thankfulness.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: grateful (a) to sb for st · gratitude (n)","example":"I am grateful to my teacher for the help, and I showed my gratitude in a short note."},{"number":82,"term":"depend on sb/st ~ rely on sb/st · dependent >< independent","sourceTerm":"depend (v) on sb/st ~ rely (v) on sb/st · dependent (a) >< independent (a)","spoken":"depend on somebody or something ~ rely on somebody or something, dependent >< independent","ipa":"/dɪˈpɛnd ɑːn ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ rɪˈlaɪ ɑːn ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ/ · /dɪˈpɛndənt ˌɪndɪˈpɛndənt/","type":"verb · adjective","meaning":"phụ thuộc, dựa vào ai hoặc điều gì · phụ thuộc · độc lập, tự lập","definition":"To need or rely on; needing support; able to act without support.","note":"depend on và rely on đều là phụ thuộc; rely on nhấn mạnh tin cậy. dependent và independent là hai tính từ đối lập.","example":"Young children depend on and rely on adults, but they become less dependent and more independent as they grow."},{"number":83,"term":"introduce A to B · introduction","sourceTerm":"introduce (v) A to B · introduction (n)","spoken":"introduce A to B · introduction","ipa":"/ˌɪntrəˈduːs ə tuː biː ˌɪntrəˈdʌkʃən/","type":"verb · noun","meaning":"giới thiệu A với B · sự hoặc lời giới thiệu","definition":"To tell two people each other's names for the first time.","note":"","example":"The teacher introduced Mai to the class; the introduction helped everyone learn her name."},{"number":84,"term":"rent ~ hire","sourceTerm":"rent (v,n) ~ hire (v)","spoken":"rent ~ hire","ipa":"/rɛnt ˈhaɪɚ/","type":"verb · noun","meaning":"thuê tài sản như nhà/xe/thiết bị ~ thuê người/dịch vụ; Anh–Anh còn dùng hire cho xe/thiết bị ngắn hạn","definition":"To pay to use property; the money paid for its use; to pay for a person or service temporarily.","note":"rent thường là thuê tài sản như nhà/xe/thiết bị. hire thường là thuê người/dịch vụ; Anh–Anh còn dùng hire cho xe/thiết bị ngắn hạn.","example":"My family rents a small flat and pays monthly rent, but it hires a cleaner for two hours each week."},{"number":85,"term":"respect · respectable · respectful","sourceTerm":"respect (v,n) · respectable (a) · respectful (a)","spoken":"respect · respectable · respectful","ipa":"/rɪˈspɛkt rɪˈspɛktəbəl rɪˈspɛktfəl/","type":"verb · noun · adjective","meaning":"kính trọng; sự kính trọng · đáng kính · thể hiện sự kính trọng","definition":"To admire and value; worthy of respect; showing respect.","note":"","example":"Students should respect others; a respectable leader listens and speaks in a respectful way."},{"number":86,"term":"ordinary · ordinary life · ordinary people","sourceTerm":"ordinary (a) · ordinary life · ordinary people","spoken":"ordinary · ordinary life · ordinary people","ipa":"/ˈɔːrdəˌnɛri ˈɔːrdəˌnɛri laɪf ˈɔːrdəˌnɛri ˈpiːpəl/","type":"adjective","meaning":"bình thường, thông thường · cuộc sống bình thường · người dân thường","definition":"Normal and not unusual; everyday life; members of the public.","note":"","example":"The film shows the ordinary life of ordinary people in a small town."},{"number":87,"term":"(im)patient · (im)patience","sourceTerm":"(im)patient (a) · (im)patience (n)","spoken":"impatient · impatience","ipa":"/ˌɪˈmpeɪʃənt ˌɪˈmpeɪʃəns/","type":"noun · adjective","meaning":"kiên nhẫn hoặc thiếu kiên nhẫn · sự kiên nhẫn hoặc thiếu kiên nhẫn","definition":"Able to wait calmly; the ability to wait calmly.","note":"","example":"A patient teacher shows patience, while an impatient teacher may speak too quickly."},{"number":88,"term":"private · privacy","sourceTerm":"private (a) · privacy (n)","spoken":"private · privacy","ipa":"/ˈpraɪvət ˈpraɪvəsi/","type":"noun · adjective","meaning":"riêng tư, cá nhân · sự riêng tư","definition":"Not for public use; freedom from unwanted attention.","note":"","example":"This is a private message, so please respect my privacy."},{"number":89,"term":"recognize · recognition","sourceTerm":"recognize (v) · recognition (n)","spoken":"recognize · recognition","ipa":"/ˈrɛkəˌɡnaɪz ˌrɛkəˈɡnɪʃən/","type":"verb · noun","meaning":"nhận ra, công nhận · sự nhận ra, sự công nhận","definition":"To know someone or something again; the act of recognizing.","note":"","example":"I recognized my old teacher, but face recognition on my phone did not."},{"number":90,"term":"by yourself ~ on your own","sourceTerm":"by yourself ~ on your own","spoken":"by yourself ~ on your own","ipa":"/baɪ jɚˈsɛlf ɑːn jɔːr oʊn/","type":"phrase / pattern","meaning":"một mình, tự mình","definition":"Alone and without help.","note":"by yourself có thể là một mình hoặc không cần giúp đỡ; on your own thường nhấn mạnh sự tự lập.","example":"Try to finish the task by yourself, or on your own, before asking for help."},{"number":91,"term":"purpose · on purpose","sourceTerm":"purpose (n) · on purpose","spoken":"purpose · on purpose","ipa":"/ˈpɝːpəs ɑːn ˈpɝːpəs/","type":"noun","meaning":"mục đích · cố ý, có chủ đích","definition":"A reason for doing something; deliberately.","note":"","example":"The purpose of the rule is safety; nobody should break it on purpose."},{"number":92,"term":"be able/unable to do st · ability · disabled · disability","sourceTerm":"be able/unable to do st · ability (n) · disabled (a) · disability (n)","spoken":"be able or unable to do something · ability · disabled · disability","ipa":"/biː ˈeɪbəl ɔːr əˈneɪbəl tuː duː ˈsʌmθɪŋ əˈbɪləˌti dɪˈseɪbəld ˌdɪsəˈbɪlɪti/","type":"noun · adjective","meaning":"có thể hoặc không thể làm gì · khả năng · khuyết tật · sự khuyết tật","definition":"Having or lacking the ability to do something; a physical or mental condition.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: be able/unable to do st · ability (n) · disabled (a) · disability (n)","example":"The student is unable to walk because of a disability, but she is able to study well and has strong writing ability."},{"number":93,"term":"admire sb for st · admirable · admiration","sourceTerm":"admire (v) sb for st · admirable (a) · admiration (n)","spoken":"admire somebody for something · admirable · admiration","ipa":"/æˈdmaɪr ˈsʌˌmbɑːdi fɔːr ˈsʌmθɪŋ ˈædmɚəbəl ˌædmɚˈeɪʃən/","type":"verb · noun · adjective","meaning":"ngưỡng mộ ai vì điều gì · đáng ngưỡng mộ · sự ngưỡng mộ","definition":"To respect someone for a quality or action.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: admire (v) sb for st · admirable (a) · admiration (n)","example":"Many students admire Lan for her admirable work and speak about her with admiration."},{"number":94,"term":"personality","sourceTerm":"personality (n)","spoken":"personality","ipa":"/ˌpɝːsəˈnælɪti/","type":"noun","meaning":"tính cách, nhân cách","definition":"The qualities that make a person behave in a particular way.","note":"","example":"Her calm and friendly personality helps the group work well."},{"number":95,"term":"relate to sb/st · related to sb/st · relation · relative · relationship","sourceTerm":"relate (v) to sb/st · related (a) to sb/st · relation (n) · relative (n) · relationship (n)","spoken":"relate to somebody or something · related to somebody or something · relation · relative · relationship","ipa":"/rɪˈleɪt tuː ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ rɪˈleɪtɪd tuː ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ riˈleɪʃən ˈrɛlətɪv riˈleɪʃəˌnʃɪp/","type":"verb · noun · adjective","meaning":"liên quan tới ai hoặc điều gì · có liên quan tới · mối liên hệ · người thân, họ hàng · mối quan hệ","definition":"To be connected with; connected; a family member; a connection between people.","note":"relation nghĩa là mối liên hệ/quan hệ; relative nghĩa là họ hàng; relationship nghĩa là mối quan hệ; relate to nghĩa là có liên quan đến.","example":"My closest relative is my aunt, and I have a good relationship with her. We are related, and our interests relate to music."},{"number":96,"term":"argue with sb about st · argument","sourceTerm":"argue (v) with sb about st · argument (n)","spoken":"argue with somebody about something · argument","ipa":"/ˈɑːrɡju wɪð ˈsʌˌmbɑːdi əˈbaʊt ˈsʌmθɪŋ ˈɑːrɡjəmənt/","type":"verb · noun","meaning":"tranh cãi, tranh luận với ai về điều gì · cuộc tranh cãi, lập luận","definition":"To disagree angrily; a disagreement.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: argue (v) with sb about st · argument (n)","example":"The students argued about the answer, but their argument ended politely."},{"number":97,"term":"jealous of sb · jealousy","sourceTerm":"jealous (a) of sb · jealousy (n)","spoken":"jealous of somebody · jealousy","ipa":"/ˈdʒɛləs ʌv ˈsʌˌmbɑːdi ˈdʒɛləsi/","type":"noun · adjective","meaning":"ghen tị với ai · sự ghen tị","definition":"Unhappy because someone has something you want; the feeling of jealousy.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: jealous (a) of sb · jealousy (n)","example":"He felt jealous of his friend's success, but he learned to control his jealousy."},{"number":98,"term":"personal · personality","sourceTerm":"personal (a) · personality (n)","spoken":"personal · personality","ipa":"/ˈpɝːsɪnəl ˌpɝːsəˈnælɪti/","type":"noun · adjective","meaning":"cá nhân, riêng tư · tính cách","definition":"Belonging to one person; the qualities that form a person's character.","note":"","example":"Her friendly personality is clear, but she keeps personal information private."},{"number":99,"term":"(dis)honest · (dis)honesty","sourceTerm":"(dis)honest (a) · (dis)honesty (n)","spoken":"dishonest · dishonesty","ipa":"/dɪˈsɑːnəst dɪˈsɑːnəsti/","type":"noun · adjective","meaning":"trung thực hoặc không trung thực · sự trung thực hoặc không trung thực","definition":"Truthful or not truthful; the quality of honesty.","note":"","example":"An honest answer shows honesty, while a dishonest answer shows dishonesty."},{"number":100,"term":"in common with sb/st","sourceTerm":"in common with sb/st","spoken":"in common with somebody or something","ipa":"/ɪn ˈkɑːmən wɪð ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ/","type":"phrase / pattern","meaning":"có điểm chung với ai / cái gì","definition":"Sharing the same interests or qualities.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: in common with sb/st","example":"Lan and Mai have music and reading in common."},{"number":101,"term":"Bring sb up","sourceTerm":"Bring sb up","spoken":"Bring somebody up","ipa":"/brɪŋ ˈsʌˌmbɑːdi ʌp/","type":"phrasal verb","meaning":"nuôi dưỡng ai","definition":"To care for and educate a child while they grow.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: Bring sb up","example":"Her grandparents brought her up to be kind and independent."},{"number":102,"term":"Fall out with sb","sourceTerm":"Fall out with sb","spoken":"Fall out with somebody","ipa":"/fɔːl aʊt wɪð ˈsʌˌmbɑːdi/","type":"phrasal verb","meaning":"cãi nhau với ai","definition":"To have an argument and stop being friendly.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: Fall out with sb","example":"The two friends fell out over a small problem but apologized later."},{"number":103,"term":"get on with sb ~ get along with sb","sourceTerm":"get on with sb ~ get along with sb","spoken":"get on with somebody ~ get along with somebody","ipa":"/ɡɛt ɑːn wɪð ˈsʌˌmbɑːdi ɡɛt əˈlɔːŋ wɪð ˈsʌˌmbɑːdi/","type":"phrasal verb","meaning":"hòa thuận, có mối quan hệ tốt với ai","definition":"To have a friendly relationship with someone.","note":"get on with và get along with đều là hòa hợp; get on phổ biến hơn trong Anh–Anh, get along phổ biến hơn trong Anh–Mỹ.","example":"I get on with my classmates and get along with my new teacher."}],"pronunciationFocus":[{"entryNumber":77,"points":[{"category":"word-stress","note":"apologize và apology đều nhấn vào phần /ˈpɑːl/"}]},{"entryNumber":79,"points":[{"category":"final-sound","note":"divorce kết thúc bằng /s/; divorced kết thúc bằng cụm /st/"}]},{"entryNumber":83,"points":[{"category":"word-stress","note":"introduce nhấn vào /ˈduːs/; introduction chuyển trọng âm sang /ˈdʌk/"}]},{"entryNumber":85,"points":[{"category":"final-sound","note":"respect kết thúc bằng cụm /kt/; giữ đủ hai phụ âm cuối"}]},{"entryNumber":89,"points":[{"category":"common-error","note":"recognize có cụm /ɡn/ ở giữa và kết thúc bằng /z/"}]},{"entryNumber":99,"points":[{"category":"silent-letter","note":"Chữ h trong honest và honesty không được phát âm"},{"category":"word-stress","note":"honest và honesty nhấn vào âm /ˈɑː/"}]},{"entryNumber":103,"points":[{"category":"linking","note":"Trong get‿on và get‿along, nối /t/ cuối get sang nguyên âm đầu của từ sau"}]}]}};
